/* Camera speed, in metres per second, at which the vignette is fully in. */

#define SPEED_FULL 10.0f

/* Camera yaw rate, in degrees per second, at which the same is true. */

#define YAW_FULL 120.0f

/*
 * Time constants for the response, in seconds. Closing has to be quicker
 * than opening: arriving late is the one failure that matters, and a
 * vignette that opens as eagerly as it closes flickers on every small
 * correction, which is its own kind of unpleasant.
 */

#define CLOSE_TIME 0.10f
#define OPEN_TIME  0.60f

/* Ignore camera motion below these, so a resting camera reads as still. */

#define SPEED_DEAD 0.60f
#define YAW_DEAD   8.00f

