    yaw   = fabsf(angle_delta(a, last_a)) / dt;

    last_p[0] = p[0];
    last_p[1] = p[1];
    last_p[2] = p[2];
    last_a    = a;

    /* Whichever of the two is worse decides. */

    target = unit(speed, SPEED_DEAD, SPEED_FULL);

